head.script:
// 테스트 설명, 유효성 값 설정
//  - body 는 화면과 함께 렌더되는 컴포넌트로 $p.dynamicCreate / remove 대상이 아니고
//    공통 생성 함수($c.gcm.createBasicXxx)도 없어 공통 base(common_M) wrap 패턴을 쓸 수 없다.
//    따라서 최초 렌더된 body 컴포넌트를 target 으로 사용하는 자체 샘플로 작성한다.
scwin.tData = {
    "description" : "[body > M > addClass]<br/>body 컴포넌트에 CSS 클래스를 추가합니다.",
    "validation" : [
        "className(필수) 파라미터로 body 컴포넌트에 추가 할 클래스 이름을 설정할 수 있어야 합니다.",
        "화면이 완전히 로드되지 않은 상태에서 클래스를 추가하면 정상적으로 적용되지 않을 수 있습니다."
    ]
}



scwin.gVar = {
    "cClass" : null
}



scwin.onpageload = function () {
    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // 정적 select1 은 초기 selectedIndex 가 적용되지 않으므로 기본값을 명시 설정
    //  dlt_className 코드값 : oddClass="1" / "oddClass evenClass"="2"
    par_className.setValue("1");

    // comp 초기 생성
    scwin.comp_init();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



// comp 생성 (Target 재생성 버튼 클릭 시 재실행)
//  body 는 동적 생성/삭제가 불가하므로 최초 렌더된 body 컴포넌트를 그대로 대상으로 사용하고,
//  "Target 재생성" 은 최초 렌더 시점의 class 상태로 되돌리는 것으로 대응한다.
scwin.comp_init = function () {
    let objBody = scwin.getBody();

    if (scwin.gVar["cClass"] === null) {
        // 최초 1회 : 초기 class 보관
        scwin.gVar["cClass"] = objBody.render.className;
    } else {
        // 재생성 : 초기 class 로 복원
        objBody.render.className = scwin.gVar["cClass"];
    }
}



// body 컴포넌트 조회
//  <body id="target1"> 로 선언해도 body 는 root 요소라 scope 전역(target1)으로 등록되지 않으며
//  $p.getComponentById("target1") 도 scope 접두어가 적용되지 않아 undefined 를 반환한다.
//  scope 접두어를 하드코딩하지 않기 위해 정적 선언된 자식(grp_main)의 parentControl 로 조회한다.
scwin.getBody = function () {
    return grp_main.parentControl;
}



// (검증) addClass : par_className 으로 선택한 클래스를 body 에 추가
scwin.btn_addClass_onclick = function (e) {
    let pClassName = par_className.getText();

    scwin.getBody().addClass(pClassName);
}



// (검증) 적용 확인 : 추가된 클래스의 스타일(oddClass=border / evenClass=border-radius)이 반영되었는지 출력
scwin.btn_getStyle_onclick = function (e) {
    let rtn = '';
    let objBody = scwin.getBody();

    rtn = objBody.getStyle("border");
    wf_body_bottom.getObj("scwin").setReturnValue("border : " + rtn);

    rtn = objBody.getStyle("border-radius");
    wf_body_bottom.getObj("scwin").setReturnValue("border-radius : " + rtn);
}
